class BindingEntry {
    String name
    String type
    boolean classValue
    boolean eventGroup
}

class BindingsConfig {
    Map<String, List<BindingEntry>> bySide = new LinkedHashMap<String, List<BindingEntry>>()

    boolean isEmpty() {
        try {
            return bySide.isEmpty()
        } catch (Throwable ignored) {
            return true
        }
    }

    List<BindingEntry> forSide(String side) {
        try {
            List<BindingEntry> l = bySide.get(side)
            return l != null ? l : Collections.emptyList()
        } catch (Throwable ignored) {
            return Collections.emptyList()
        }
    }
}

class BindingsSupport {
    static final Logger LOG = Logger.getInstance("KubeGroovyBindings")
    static boolean DEBUG = false
    static final String EVENT_GROUP_BINDING = "dev.uncandango.kubegroovy.typing.EventGroupBinding"
    static final List<String> SIDES = ["startup", "server", "client"]
    private static final Pattern TOP_STATEMENT = Pattern.compile("(?m)^(package\\s+[\\w.]+|import\\s+[\\w.*]+)")
    private static File configFile = null
    private static long configStamp = -1L
    private static BindingsConfig cached = new BindingsConfig()
    private static File logoFile = null
    private static File logoDarkFile = null
    private static File logoSvgFile = null
    private static File logoDarkSvgFile = null
    private static Icon logo = null
    private static String logoSource = null

    static void debug(String message) {
        if (!DEBUG) return
        try {
            LOG.info("[bindings] " + message)
        } catch (Throwable ignored) {}
    }

    static void setConfigFile(File f) {
        try {
            configFile = f
        } catch (Throwable ignored) {}
    }

    /**
     * Tells the icon loader where the logo lives. Called once from the
     * script body with LivePlugin's `pluginPath` (the folder this script runs
     * from). The pre-rendered 32px PNG masters ({@code logo.png} /
     * {@code logo-dark.png}) are the deterministic fallback: plain Swing with
     * no platform SVG involvement. When both are missing, {@link #logo()}
     * just returns null and entries render text-only.
     */
    static void setLogoFile(File png) {
        try {
            logoFile = png
            logo = null
            logoSource = null
        } catch (Throwable ignored) {}
    }

    static void setLogoDarkFile(File png) {
        try {
            logoDarkFile = png
            logo = null
            logoSource = null
        } catch (Throwable ignored) {}
    }

    /**
     * Vector sources for the crisp path ({@link #logo()} attaches the SVG
     * raw so the platform rasterizes it per paint at the display's exact
     * scale). PNG masters above remain the fallback.
     */
    static void setLogoSvgFile(File svg) {
        try {
            logoSvgFile = svg
            logo = null
            logoSource = null
        } catch (Throwable ignored) {}
    }

    static void setLogoDarkSvgFile(File svg) {
        try {
            logoDarkSvgFile = svg
            logo = null
            logoSource = null
        } catch (Throwable ignored) {}
    }

    /**
     * True on a dark IDE theme. Panel-background luminance is the primary
     * signal so old Darcula, New UI Dark, and custom dark themes are all
     * covered even as LaF names/APIs change; the Darcula checks below are
     * fallbacks so a renamed/removed API never breaks completion.
     */
    static boolean isDarkUI() {
        try {
            java.awt.Color bg = javax.swing.UIManager.getColor("Panel.background")
            if (bg != null) {
                double lum = (0.2126 * bg.getRed() + 0.7152 * bg.getGreen() + 0.0722 * bg.getBlue()) / 255.0
                return lum < 0.5
            }
        } catch (Throwable ignored) {}
        try {
            if (com.intellij.util.ui.UIUtil.isUnderDarcula()) return true
        } catch (Throwable ignored) {}
        try {
            String name = javax.swing.UIManager.getLookAndFeel()?.getName()
            if (name != null && name.toLowerCase(java.util.Locale.ROOT).contains("darcula")) return true
        } catch (Throwable ignored) {}
        return false
    }

    /**
     * Loads the logo once and caches it. Never fail completion for art:
     * null means text-only entry. Failures are never cached, so a later
     * completion retries (e.g. artwork installed after this script loaded).
     *
     * The SVG wins when it resolves: it is attached raw — the same way every
     * IntelliJ plugin icon is attached — so the platform rasterizes it per
     * paint at the display's exact scale and rows stay crisp on HiDPI. A
     * frozen snapshot would stretch and blur there (16px raster on a 250%
     * display reads as a broken smudge), which is why this method must not
     * rasterize vectors itself. The 32px PNG masters are the deterministic
     * fallback when the vector path cannot resolve.
     */
    static Icon logo() {
        try {
            if (logo != null) return logo
            boolean dark = isDarkUI()
            List<File> svgs = dark ? [logoDarkSvgFile, logoSvgFile] : [logoSvgFile, logoDarkSvgFile]
            for (File svg : svgs) {
                try {
                    Icon v = vectorLogo(svg)
                    if (v != null) {
                        logo = v
                        logoSource = svg.getName()
                        return logo
                    }
                } catch (Throwable ignored) {}
            }
            List<File> pngs = dark ? [logoDarkFile, logoFile] : [logoFile, logoDarkFile]
            for (File png : pngs) {
                try {
                    Icon p = pngLogo(png)
                    if (p != null) {
                        logo = p
                        logoSource = png.getName()
                        return logo
                    }
                } catch (Throwable ignored) {}
            }
            return null
        } catch (Throwable ignored) {
            return null
        }
    }

    /**
     * Returns the SVG icon itself when it synchronously resolves to a sane
     * lookup size, else null. A 1x1 result means the load failed (the
     * platform's empty icon); absurd dimensions would blow up the completion
     * row — both fall through to the PNG masters instead of attaching a
     * broken icon.
     */
    static Icon vectorLogo(File svg) {
        try {
            if (svg == null || !svg.isFile()) return null
            Icon raw = IconLoader.findIcon(svg.toURI().toURL(), true)
            if (raw == null) return null
            int w = 0
            int h = 0
            try {
                w = raw.getIconWidth()
                h = raw.getIconHeight()
            } catch (Throwable ignored) {
                return null
            }
            if (w < 2 || h < 2 || w > 48 || h > 48) return null
            return raw
        } catch (Throwable ignored) {
            return null
        }
    }

    /**
     * Loads a pre-rendered PNG master (32px), bicubic-downscaled to the
     * 16x16 lookup size. Returns null when the file is missing/unreadable.
     */
    static Icon pngLogo(File png) {
        try {
            if (png == null || !png.isFile()) return null
            ImageIcon raw = new ImageIcon(png.getAbsolutePath())
            if (raw.getIconWidth() <= 0) return null
            if (raw.getIconWidth() == 16 && raw.getIconHeight() == 16) return raw
            return new ImageIcon(scalePng(raw.getImage(), 16, 16))
        } catch (Throwable ignored) {
            return null
        }
    }

    /**
     * Downscales in halving steps with bicubic interpolation instead of one
     * {@code getScaledInstance} jump: single-step scaling of a large logo is
     * what makes 16px results look mushy. Skipped when already 16x16.
     */
    static java.awt.Image scalePng(java.awt.Image src, int w, int h) {
        try {
            int cw = src.getWidth(null)
            int ch = src.getHeight(null)
            java.awt.Image cur = src
            while (cw / 2 >= w && ch / 2 >= h) {
                cw = cw.intdiv(2)
                ch = ch.intdiv(2)
                cur = downscaleStep(cur, cw, ch)
            }
            return downscaleStep(cur, w, h)
        } catch (Throwable ignored) {
            return src
        }
    }

    private static java.awt.Image downscaleStep(java.awt.Image src, int w, int h) {
        try {
            java.awt.image.BufferedImage out = new java.awt.image.BufferedImage(w, h, java.awt.image.BufferedImage.TYPE_INT_ARGB)
            java.awt.Graphics2D g = out.createGraphics()
            try {
                g.setRenderingHint(java.awt.RenderingHints.KEY_INTERPOLATION, java.awt.RenderingHints.VALUE_INTERPOLATION_BICUBIC)
                g.setRenderingHint(java.awt.RenderingHints.KEY_RENDERING, java.awt.RenderingHints.VALUE_RENDER_QUALITY)
                g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON)
                g.drawImage(src, 0, 0, w, h, null)
            } finally {
                try { g.dispose() } catch (Throwable ignored) {}
            }
            return out
        } catch (Throwable ignored) {
            return src
        }
    }

    static synchronized BindingsConfig load() {
        try {
            if (configFile == null || !configFile.isFile()) return cached
            long stamp = configFile.lastModified()
            if (stamp == configStamp) return cached
            Map parsed = null
            try {
                Object o = new ObjectMapper().readValue(configFile, Map.class)
                if (o instanceof Map) parsed = (Map) o
            } catch (Throwable t) {
                debug("config parse failed, keeping last good (" + t + ")")
                return cached
            }
            if (parsed == null) return cached
            BindingsConfig next = new BindingsConfig()
            try {
                for (String side : SIDES) {
                    Object list = parsed.get(side)
                    if (!(list instanceof Collection)) continue
                    for (def e : (Collection) list) {
                        try {
                            if (!(e instanceof Map)) continue
                            Map m = (Map) e
                            Object n = m.get("name")
                            Object t = m.get("type")
                            if (n == null || t == null) continue
                            BindingEntry entry = new BindingEntry()
                            entry.name = n.toString().trim()
                            entry.type = t.toString().trim()
                            if (entry.name.isEmpty() || entry.type.isEmpty()) continue
                            entry.classValue = toBool(m.get("classValue"))
                            entry.eventGroup = toBool(m.get("eventGroup"))
                            List<BindingEntry> l = next.bySide.get(side)
                            if (l == null) {
                                l = new ArrayList<BindingEntry>()
                                next.bySide.put(side, l)
                            }
                            l.add(entry)
                        } catch (Throwable ignored2) {}
                    }
                }
            } catch (Throwable ignored) {}
            cached = next
            configStamp = stamp
            debug("config loaded sides=" + next.bySide.keySet())
        } catch (Throwable ignored) {}
        return cached
    }

    static boolean toBool(Object o) {
        try {
            if (o instanceof Boolean) return ((Boolean) o).booleanValue()
            if (o != null) return Boolean.parseBoolean(o.toString().trim())
        } catch (Throwable ignored) {}
        return false
    }

    static String sideForFile(PsiFile file) {
        try {
            // Completion often passes a non-physical DummyHolder copy of the
            // file; its virtual file is meaningless, so resolve the original.
            try {
                def original = file?.getOriginalFile()
                if (original != null) file = (PsiFile) original
            } catch (Throwable ignored) {}
            String path = ""
            try {
                path = file?.getVirtualFile()?.getPath() ?: ""
            } catch (Throwable ignored) {}
            if (path.contains("startup_scripts")) return "startup"
            if (path.contains("server_scripts")) return "server"
            if (path.contains("client_scripts")) return "client"
        } catch (Throwable ignored) {}
        return null
    }

    static String variableType(BindingEntry entry) {
        try {
            if (entry.eventGroup) return EVENT_GROUP_BINDING
            if (entry.classValue) return "java.lang.Class<" + entry.type + ">"
            return entry.type
        } catch (Throwable ignored) {
            return "java.lang.Object"
        }
    }

    static boolean accepts(PsiScopeProcessor processor, ElementClassHint.DeclarationKind... kinds) {
        try {
            def hint = processor.getHint(ElementClassHint.KEY)
            if (hint == null) return true
            for (def kind : kinds) {
                try {
                    if (hint.shouldProcess(kind)) return true
                } catch (Throwable ignored) {}
            }
            return false
        } catch (Throwable ignored) {
            return true
        }
    }

    /**
     * Line-based check for an existing import of a class (exact or aliased).
     * Text-based on purpose (same rationale as type-suggestions): the document
     * was just edited and PSI may be stale. A star import does NOT count: it
     * cannot provide the $ alias.
     */
    static boolean hasClassImport(String text, String fqn) {
        try {
            for (String line : text.readLines()) {
                String t = line.trim()
                if (!t.startsWith("import ")) continue
                String rest = t.substring(7).trim()
                if (rest.endsWith(";")) rest = rest.substring(0, rest.length() - 1).trim()
                if (rest.equals(fqn) || rest.startsWith(fqn + " ") || rest.startsWith(fqn + "\t")) return true
            }
        } catch (Throwable ignored) {}
        return false
    }

    static boolean hasAliasImport(String text, String fqn, String alias) {
        try {
            for (String line : text.readLines()) {
                String t = line.trim()
                if (!t.startsWith("import ")) continue
                String rest = t.substring(7).trim()
                if (rest.endsWith(";")) rest = rest.substring(0, rest.length() - 1).trim()
                if (rest.equals(fqn + " as " + alias)) return true
            }
        } catch (Throwable ignored) {}
        return false
    }

    /**
     * Document offset where a new import line belongs: end of the line holding
     * the last {@code package}/import statement, else 0. Same convention as
     * type-suggestions, extended to end-of-line: aliased imports
     * ({@code import FQN as $Alias}) continue past what the statement matcher
     * covers, and inserting mid-line would split them and strand alias tails
     * onto the new import.
     */
    static int importInsertionOffset(String text) {
        try {
            Matcher m = TOP_STATEMENT.matcher(text)
            int lastEnd = -1
            while (m.find()) lastEnd = m.end()
            if (lastEnd >= 0) {
                int nl = text.indexOf("\n", lastEnd)
                return nl >= 0 ? nl : text.length()
            }
            if (text.startsWith("#!")) {
                int nl = text.indexOf('\n')
                return nl >= 0 ? nl : text.length()
            }
            return 0
        } catch (Throwable ignored) {
            return 0
        }
    }

    /**
     * Insert handler for class-value bindings: ensures
     * {@code import <FQN> as <alias>} exists (skipped when the class is
     * already imported — the implicit variable contributor below still
     * resolves the name), then replaces the typed prefix with the alias.
     * Insert handlers run inside a write action, so direct document edits
     * are legal here.
     */
    static InsertHandler<LookupElement> aliasInsertHandler(String fqn, String alias) {
        return { InsertionContext ctx, LookupElement item ->
            try {
                def doc = ctx.getDocument()
                String text = ""
                try {
                    text = doc.getText()
                } catch (Throwable ignored) {}
                int shift = 0
                try {
                    if (!hasAliasImport(text, fqn, alias) && !hasClassImport(text, fqn)) {
                        int at = importInsertionOffset(text)
                        String line = at > 0
                            ? "\nimport " + fqn + " as " + alias
                            : "import " + fqn + " as " + alias + "\n"
                        doc.insertString(at, line)
                        shift = line.length()
                    }
                } catch (Throwable ignored) {}
                ctx.commitDocument()
                int start = ctx.getStartOffset() + shift
                int tail = ctx.getTailOffset() + shift
                try {
                    doc.replaceString(start, tail, alias)
                } catch (Throwable ignored2) {
                    try {
                        doc.insertString(tail, alias)
                    } catch (Throwable ignored3) {}
                }
                try {
                    ctx.getEditor().getCaretModel().moveToOffset(start + alias.length())
                } catch (Throwable ignored2) {}
                ctx.commitDocument()
            } catch (Throwable ignored) {}
        } as InsertHandler<LookupElement>
    }
}

class BindingsContributor extends NonCodeMembersContributor implements DumbAware {
    @Override
    void processDynamicElements(PsiType qualifierType, PsiScopeProcessor processor, PsiElement place, ResolveState state) {
        if (!(place instanceof GrReferenceExpression)) {
            BindingsSupport.debug("contributor: place is not a reference (" + place?.getClass()?.getName() + ")")
            return
        }
        GrReferenceExpression ref = (GrReferenceExpression) place
        try {
            if (ref.getQualifierExpression() != null) return
        } catch (Throwable ignored) {
            return
        }
        String side = null
        try {
            side = BindingsSupport.sideForFile(place.getContainingFile())
        } catch (Throwable ignored) {}
        if (side == null) {
            BindingsSupport.debug("contributor: no side for file=" + place?.getContainingFile())
            return
        }
        if (!BindingsSupport.accepts(processor, ElementClassHint.DeclarationKind.VARIABLE)) return
        String wanted = null
        try {
            def hint = processor.getHint(NameHint.KEY)
            if (hint != null) wanted = hint.getName(state)
        } catch (Throwable ignored) {}
        List<BindingEntry> entries = BindingsSupport.load().forSide(side)
        if (entries.isEmpty()) return
        BindingsSupport.debug("contributor: side=" + side + " wanted=" + wanted + " entries=" + entries.size())
        def mgr = null
        try {
            mgr = place.getManager()
        } catch (Throwable ignored) {}
        if (mgr == null) return
        for (BindingEntry entry : entries) {
            try {
                if (wanted != null && !wanted.equals(entry.name)) continue
                // Class values resolve through their explicit
                // `import <FQN> as <name>` (offered by completion below);
                // a bare java.lang.Class helps nothing in scripts.
                if (entry.classValue) continue
                String type = BindingsSupport.variableType(entry)
                def prop = new GrDynamicImplicitProperty(mgr, entry.name, type, type)
                try {
                    ResolveUtil.processElement(processor, prop, state)
                } catch (Throwable ignored2) {}
            } catch (Throwable ignored2) {}
        }
    }
}

/**
 * Relevance boost for our binding rows: matched names sort before everything
 * else while keeping the platform's default order (ML, proximity, ...) for
 * the rest — appended weighers only break ties, never replace ranking.
 */
class BindingsBoostWeigher extends LookupElementWeigher {
    private final Set<String> names

    BindingsBoostWeigher(Set<String> names) {
        super("kgyBindingsBoost")
        Set<String> safe = new HashSet<String>()
        try {
            if (names != null) safe.addAll(names)
        } catch (Throwable ignored) {}
        this.names = safe
    }

    @Override
    Comparable weigh(LookupElement element) {
        try {
            String s = element.getLookupString()
            if (s != null && names.contains(s)) return 0
        } catch (Throwable ignored) {}
        return 1
    }
}

class BindingsCompletionProvider extends CompletionProvider<CompletionParameters> {
    @Override
    protected void addCompletions(CompletionParameters parameters, ProcessingContext context, CompletionResultSet result) {
        try {
            PsiElement position = parameters.getPosition()
            GrReferenceExpression ref = null
            try {
                ref = com.intellij.psi.util.PsiTreeUtil.getParentOfType(position, GrReferenceExpression.class, false)
            } catch (Throwable ignored) {}
            if (ref == null) return
            try {
                if (ref.getQualifierExpression() != null) return
            } catch (Throwable ignored) {
                return
            }
            PsiFile file = null
            try {
                file = position.getContainingFile()
            } catch (Throwable ignored) {}
            String side = BindingsSupport.sideForFile(file)
            if (side == null) {
                BindingsSupport.debug("completion: no side")
                return
            }
            int offered = 0
            List<BindingEntry> sideEntries = BindingsSupport.load().forSide(side)
            Set<String> boostNames = new HashSet<String>()
            for (BindingEntry probe : sideEntries) {
                try {
                    if (probe.classValue && probe.name != null) boostNames.add(probe.name)
                } catch (Throwable ignored2) {}
            }
            def sink = result
            try {
                def sorter = CompletionSorter.defaultSorter(parameters, result.getPrefixMatcher())
                    .weigh(new BindingsBoostWeigher(boostNames))
                sink = result.withRelevanceSorter(sorter)
            } catch (Throwable ignored2) {}
            for (BindingEntry entry : sideEntries) {
                try {
                    if (!entry.classValue) continue
                    def el = LookupElementBuilder.create(entry.name)
                        .withTypeText(entry.type)
                        .withInsertHandler(BindingsSupport.aliasInsertHandler(entry.type, entry.name))
                    try {
                        Icon icon = BindingsSupport.logo()
                        if (icon != null) el = el.withIcon(icon)
                    } catch (Throwable ignored2) {}
                    sink.addElement(el)
                    offered++
                } catch (Throwable ignored2) {}
            }
            BindingsSupport.debug("completion: side=" + side + " offered=" + offered)
        } catch (Throwable ignored) {}
    }
}

class BindingsCompletionContributor extends CompletionContributor {
    BindingsCompletionContributor() {
        extend(CompletionType.BASIC, PlatformPatterns.psiElement(), new BindingsCompletionProvider())
    }
}

// --- LivePlugin registration (unregistered automatically via pluginDisposable) ---
try {
    BindingsSupport.setConfigFile(new File(pluginPath?.toString() ?: "", "bindings.json"))
    BindingsSupport.setLogoFile(new File(pluginPath?.toString() ?: "", "logo.png"))
    BindingsSupport.setLogoDarkFile(new File(pluginPath?.toString() ?: "", "logo-dark.png"))
    BindingsSupport.setLogoSvgFile(new File(pluginPath?.toString() ?: "", "logo.svg"))
    BindingsSupport.setLogoDarkSvgFile(new File(pluginPath?.toString() ?: "", "logo-dark.svg"))
    // Always-on one-liner so idea.log shows which logo (if any) the rows use.
    try {
        Icon probe = BindingsSupport.logo()
        BindingsSupport.LOG.info("[bindings] logo=" + (probe == null ? "none" : BindingsSupport.logoSource + " " + probe.getIconWidth() + "x" + probe.getIconHeight()))
    } catch (Throwable ignored) {}
} catch (Throwable ignored) {}
try {
    ExtensionPointName.create("org.intellij.groovy.membersContributor").point
        .registerExtension(new BindingsContributor(), pluginDisposable)
} catch (Throwable ignored) {}
def bindingsDescriptor = new DefaultPluginDescriptor(PluginId.getId("LivePlugin"), BindingsCompletionContributor.classLoader)
def bindingsPoint = ExtensionPointName.create("com.intellij.completion.contributor")
bindingsPoint.point.registerExtension(
    new CompletionContributorEP("Groovy", BindingsCompletionContributor.name, bindingsDescriptor),
    LoadingOrder.FIRST, pluginDisposable)
